+
+    .question[aria-expanded="true"] .icon::after {
+      transform: rotate(0deg);
+    }
+
+    .details {
+      padding: 0 28px 28px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.75;
+    }
